from pathlib import Path
import json,hashlib
root=Path.cwd()
home=Path.home()
prod=home/'prediction_research_prod'
def read(p):
    if not p.is_file() or p.is_symlink(): return None
    obj=json.loads(p.read_text())
    return obj if isinstance(obj,dict) else None
tasks={
'final':('DEV-PRED-REQUESTED-REPAIRS-FINAL-ACCEPT-20261005','8511127a874f323cc46cf701b2e9286d287f0b9a',7),
'targeted':('DEV-PRED-REPAIRS-TARGETED-VERIFY-R2-20261005','06f77566e538d8e0eaa5dd9e97744515a0ee55a7',4)}
records={}
for label,(tid,source,count) in tasks.items():
    r=read(home/'.local/state/prediction-project-executor'/(tid+'.json'))
    records[label]={'task_id':tid,'status':(r or {}).get('status','MISSING'),'source_commit':(r or {}).get('source_commit'),'operation_count':(r or {}).get('operation_count'),'completed_at_utc':(r or {}).get('completed_at_utc'),'proven':bool(r and r.get('task_id')==tid and r.get('status')=='PASS' and r.get('source_commit')==source and r.get('operation_count')==count)}
files={'supervisor':'control/codex_supervisor/supervisor.py','report':'control/hourly/candidate_reporting.py'}
diff=[]
for label,rel in files.items():
    p=prod/rel
    if not p.is_file() or p.is_symlink() or hashlib.sha256(p.read_bytes()).hexdigest()!=hashlib.sha256((root/rel).read_bytes()).hexdigest():diff.append(label)
mapping={'candidate_dispatch.py_sha256':'control/codex_supervisor/candidate_dispatch.py','candidate_policy_sha256':'control/hourly/candidate_queue.py','evidence_wake.py_sha256':'control/codex_supervisor/evidence_wake.py','build_wake.py_sha256':'control/codex_supervisor/build_wake.py','model_quality_gate.py_sha256':'control/codex_supervisor/model_quality_gate.py','astra_review_wake.py_sha256':'control/codex_supervisor/astra_review_wake.py','measurement_wake.py_sha256':'control/codex_supervisor/measurement_wake.py','supervisor_sha256':'control/codex_supervisor/supervisor.py','astra_autonomous_review.py_sha256':'control/codex_supervisor/astra_autonomous_review.py'}
cfg=read(prod/'knowledge/codex_runtime/CONFIG.json') or {}
bad=[]
for key,rel in mapping.items():
    p=prod/rel
    if not p.is_file() or p.is_symlink() or cfg.get(key)!=hashlib.sha256(p.read_bytes()).hexdigest():bad.append(key)
result={'receipts':records,'production_diff':diff,'production_bad_pins':bad,'full_system_test_run':False,'production_modified':False}
out=root/'diagnostic-result'
out.mkdir(exist_ok=True)
(out/'repair-acceptance.json').write_text(json.dumps(result,indent=2))
compact={'final':records['final']['status'],'final_proven':records['final']['proven'],'targeted':records['targeted']['status'],'prod_diff':diff,'bad_pins':[x.replace('.py_sha256','').replace('_sha256','') for x in bad]}
print('REPAIR_ACCEPTANCE '+json.dumps(compact,separators=(',',':')),flush=True)
raise SystemExit(0 if records['final']['proven'] and not diff and not bad else 1)
